  ["Especializaciones contradictorias: comprueba el libro de hechizos."] = "Conflicting specializations: check the spellbook.",
  ["No se detecta una especialización aprendida en el libro de hechizos."] = "No learned specialization detected in the spellbook.",
  ["Especialización actual sin confirmar; consulta el libro de hechizos."] = "Current specialization unconfirmed; check the spellbook.",
  ["Herrería: las ramas documentadas son armaduras y armas; armas tiene ramas de hachas, martillos y espadas. Confirma los desbloqueos y requisitos en Forever. No se elige ninguna automáticamente."] = "Blacksmithing: documented branches are armor and weapons; weapons branches into axes, hammers and swords. Confirm unlocks and requirements in Forever. None is selected automatically.",
  ["Reservas opcionales orientativas. Una misión completada no acredita una especialización vigente. Confirma el desbloqueo antes de comprar."] = "Approximate optional reserves. A completed quest does not establish a current specialization. Confirm the unlock before buying.",
  ["Paradas orientativas: no se ha verificado la densidad de recursos ni la accesibilidad de cada punto."] = "Approximate stops: resource density and accessibility have not been verified at each point.",
  ["Límite de profesión alcanzado: puedes recolectar materiales, pero no ganar más habilidad hasta desbloquear el siguiente rango."] = "Profession cap reached: you can gather materials, but cannot gain more skill until you unlock the next rank.",
  ["Compra (instantánea): bolsas y banco personal consultado si el cliente devuelve datos válidos. Vuelve a generar la lista tras mover materiales."] = "Shopping (snapshot): bags and personal bank queried if the client returns valid data. Generate the list again after moving materials.",
  ["Compra (instantánea): solo bolsas; banco sin comprobar. Abre el banco y vuelve a generar la lista."] = "Shopping (snapshot): bags only; bank unchecked. Open the bank and generate the list again.",
  ["En bolsas: "] = "In bags: ",
